'use strict';
const $=s=>document.querySelector(s),E=SpreadEngine;
const state={metals:{range:90,rows:[],name:'同梱TFX日足',entry:'',date:'',side:1},indices:{range:90,rows:[],name:'同梱TFX日足',entry:'',date:'',side:-1,strategy:'b'}};
const num=(v,d=1)=>v===null||v===undefined||!Number.isFinite(v)?'—':v.toLocaleString('ja-JP',{minimumFractionDigits:d,maximumFractionDigits:d});
const sign=(v,d=1)=>v===null?'—':(v>0?'+':'')+num(v,d);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message,error=false){$('#notice').className=error?'error':'success';$('#notice').textContent=message;}
function metric(label,value,sub,cls=''){return `<div class="metric"><div class="label">${label}</div><div class="value ${cls}">${value}</div><div class="sub">${sub}</div></div>`;}
function check(ok,label){return `<span class="check ${ok?'yes':''}">${ok?'✓':'○'} ${label}</span>`;}
function section(kind){const a=state[kind],m=kind==='metals',d=E.derive(a.rows,kind);a.data=d;const r=d.at(-1),dec=m?1:0,move=r.change===null?'判定待ち':r.change<0?'縮小':r.change>0?'拡大':'横ばい',trend=r.regime==='unknown'?'50日未満':r.regime==='contraction'?'縮小トレンド':r.regime==='expansion'?'拡大トレンド':'横ばい';const title=m?'銀−プラチナ サヤ管理':'日経225−NYダウ サヤ取り';
return `<section class="section" id="${kind}"><div class="sectionhead"><div><div class="titleline"><span class="section-index">${m?'01':'02'}</span><h2>${title}</h2></div><p class="formula">${m?'Spread = 3 × Silver − Platinum':'Spread = NY_DOW − NIKKEI225'}</p></div><div class="tools"><label class="filebtn">CSVで更新<input type="file" accept=".csv,text/csv" data-import="${kind}" aria-label="${title} CSV読み込み"></label><button data-export="${kind}">CSVを書き出す</button></div></div>
<div class="meta"><span>データ最終日 <b>${r.date}</b></span><span>${d.length}営業日</span><span>出典：保存済みTFX価格 / ${esc(a.name)}</span></div><div class="metrics">${metric('最新サヤ',num(r.spread,dec)+' <small style="font-size:14px">pt</small>',m?'銀3枚：プラチナ1枚':'NYダウ終値 − 日経225終値')}${metric('前日比',sign(r.change,dec)+' <small style="font-size:14px">pt</small>',move,r.change<0?'down':'up')}${metric(m?'銀 / プラチナ':'NYダウ / 日経225',m?num(r.silver,1):num(r.ny_dow_close,0),m?'プラチナ '+num(r.platinum,1):'日経225 '+num(r.nikkei225_close,0))}${metric(m?'V3 シグナル':'MAによる市場状態',m?(r.v3===1?'拡大候補':r.v3===-1?'縮小候補':d.length<7?'データ不足':'見送り'):trend,m?'固定水準＋反転条件':'20MA '+num(r.ma20,0)+' / 50MA '+num(r.ma50,0))}</div>
<div class="grid"><div class="card"><div class="cardhead"><h3>サヤ推移</h3><div class="ranges" aria-label="表示期間">${[30,90,0].map(n=>`<button data-range="${kind}" data-days="${n}" class="${a.range===n?'active':''}" aria-pressed="${a.range===n}">${n?n+'日':'全期間'}</button>`).join('')}</div></div><div class="legend"><span><i style="background:#236fbd"></i>サヤ</span>${m?'<span><i style="background:#8496a8"></i>固定水準 2,200 / 2,500</span>':'<span><i style="background:#0a8b83"></i>20MA</span><span><i style="background:#d49734"></i>50MA</span>'}</div><div class="chartwrap"><canvas data-chart="${kind}" role="img" aria-label="${title} 日次サヤ推移。詳細な値は下の直近日足を参照。"></canvas></div><div class="chart-readout" data-readout="${kind}">${r.date}　サヤ ${num(r.spread,dec)} pt</div></div><div class="card"><h3>現在のシグナル・エントリー候補</h3>${m?metalSignal(r,d.length):indexSignals(r,d)}</div></div>
<div class="card exitpanel"><div><h3>保有ポジション・決済目安</h3><p class="help">実際の建値を入力すると、その建値で再計算します。未入力時は${m?'最新サヤを仮の建値として表示':'OOS仮想保有、なければ最新サヤを仮の建値として表示'}。</p><div class="entryfields">${m?`<label>方向<select data-field="side" data-kind="${kind}"><option value="1" ${a.side===1?'selected':''}>銀3買い / Pt1売り</option><option value="-1" ${a.side===-1?'selected':''}>銀3売り / Pt1買い</option></select></label>`:`<label>戦略<select data-field="strategy" data-kind="${kind}"><option value="b" ${a.strategy==='b'?'selected':''}>Strategy B</option><option value="c2" ${a.strategy==='c2'?'selected':''}>Candidate C2</option></select></label>`}<label>エントリーサヤ<input type="number" step="0.1" placeholder="未入力" value="${esc(a.entry)}" data-field="entry" data-kind="${kind}" aria-label="${title} エントリーサヤ"></label><label>約定日<input type="date" value="${esc(a.date)}" max="${r.date}" data-field="date" data-kind="${kind}" aria-label="${title} 約定日"></label></div></div><div data-exit="${kind}">${exitView(kind)}</div></div>
<details><summary>固定ルール・CSVの使い方・直近日足</summary><p>${m?'正式V3：直前5営業日の変化の60%以上が同方向、純変化300pt以上、当日反転。拡大側は2,200以下、縮小側は2,500以上。固定水準のみ・反転決済B、損切り800pt、最大15営業日。シグナル日の翌有効日終値で約定。元サイトにあった−900ptは暫定目安で、正式V3とは区別しています。':'Strategy B：20MA &lt; 50MA、直前の連続拡大合計500pt以上から当日マイナス反転。C2：Bの全条件 ＋ 10営業日Spread変化 &lt; 0。終値で判定、翌共通有効日始値で約定。利確1,000pt、損切り2,000pt、最大30営業日。同時保有1。保有中は新規エントリーせず、MAの変化だけでは決済しません。<br>2026-10-02以前は研究期間、2026-10-03以降は固定OOS。仮想ポジションはOOS開始時に保有なしで計算し、CSVの終端では強制決済しません。2026年限を継続し、他年限へ自動切り替えしません。'} </p><p>CSVの必須列：<code>${m?'Date,Silver,Platinum':'date,ny_dow_close,nikkei225_close'}</code>${m?'':'。仮想保有の計算には <code>ny_dow_open,nikkei225_open</code> も必要です。始値がない場合、シグナルのみ計算します'}。日付はYYYY-MM-DD、価格は正数。同じ取引日の価格を使ってください。CSV読み込みは現在の全履歴を置き換えます。日付重複・欠損価格はエラーとして表示し、現在のデータを保持します。</p><p>取り込んだデータはこの画面内で使います。更新後にCSVを書き出すと、次回も再読み込みできます。B/C2には最低50共通営業日、10日変化には11日、V3には7日が必要です。</p><div class="tablewrap"><table><thead><tr><th>日付</th><th>${m?'銀':'NYダウ'}</th><th>${m?'プラチナ':'日経225'}</th><th>サヤ</th><th>前日比</th><th>${m?'V3':'B / C2'}</th></tr></thead><tbody>${d.slice(-10).reverse().map(x=>`<tr><td>${x.date}</td><td>${num(m?x.silver:x.ny_dow_close,dec)}</td><td>${num(m?x.platinum:x.nikkei225_close,dec)}</td><td>${num(x.spread,dec)}</td><td>${sign(x.change,dec)}</td><td>${m?(x.v3===1?'拡大':x.v3===-1?'縮小':'—'):(x.b?'成立':'—')+' / '+(x.c2?'成立':'—')}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
function metalSignal(r,n){const text=r.v3===1?'銀3枚買い ＋ Pt1枚売り':r.v3===-1?'銀3枚売り ＋ Pt1枚買い':n<7?'判定に7営業日必要':'新規エントリーを見送り';return `<div class="signal"><div class="signalhead"><strong>固定V3</strong><span class="badge ${r.v3?'teal':''}">${r.v3?'候補成立':n<7?'データ不足':'候補なし'}</span></div><p><strong>${text}</strong></p><p>確定終値で反転を確認し、翌有効日終値で約定。サヤ水準だけではエントリーしません。</p><div class="checklist">${check(r.spread<=2200,'拡大水準 ≤ 2,200')}${check(r.spread>=2500,'縮小水準 ≥ 2,500')}${check(!!r.v3,'方向比率・変化幅・反転')}</div></div>`;}
function indexSignals(r,d){return ['b','c2'].map(k=>{const sim=E.simulate(d,k),active=r[k],stateText=r.ma50===null?'データ不足':sim.position?'仮想保有中':active?'候補成立':'候補なし';return `<div class="signal"><div class="signalhead"><strong>${k==='b'?'Strategy B':'Candidate C2'}</strong><span class="badge ${active?'teal':sim.position?'blue':''}">${stateText}</span></div><p>${sim.position?'OOS仮想保有：NYダウ売り ＋ 日経225買い':active?'NYダウ売り ＋ 日経225買い<br>翌共通取引日始値がエントリー候補':r.ma50===null?'50共通営業日がそろうと判定します':'本日の新規エントリー候補はありません。'}</p><div class="checklist">${check(r.regime==='contraction','20MA < 50MA')}${check(r.pullback>=500,'連続拡大 ≥ 500pt')}${check(r.change<0,'当日縮小反転')}${k==='c2'?check(r.change10!==null&&r.change10<0,'10日変化 < 0'):''}</div><p>${k==='c2'?'10営業日変化 '+sign(r.change10,0)+' pt ・研究候補として条件固定':'縮小トレンド限定 ・既存Phase 3条件固定'}${sim.position&&active?' / シグナルは成立していますが、保有中の新規取引は見送りします。':''}</p></div>`;}).join('');}
function exitView(kind){const a=state[kind],m=kind==='metals',r=a.data.at(-1),manual=a.entry!==''&&Number.isFinite(+a.entry),sim=m?null:E.simulate(a.data,a.strategy);const p=sim?.position;const entry=manual?+a.entry:p?p.entry:r.spread,side=m?a.side:-1,date=manual?a.date:p?p.date:'';const profit=m?entry+side*300:entry-1000,stop=m?entry-side*800:entry+2000,pnl=side*(r.spread-entry),held=date?a.data.filter(x=>x.date>=date).length:null;const invalidDate=!!date&&(date>r.date||!a.data.some(x=>x.date===date));const pending=!m&&!manual?sim.pendingExit:null;const label=manual?'入力した実ポジションの目安':p?'OOS仮想ポジション': '未保有 / 最新サヤを仮の建値として表示';return `<div class="meta"><span class="badge ${manual||p?'blue':''}">${label}</span><span>建値 ${num(entry,m?1:0)}${date?' / '+esc(date):''}</span></div><div class="exitnumbers"><div><span>${m?'反転利確の最低利益水準':'利確判定サヤ'}</span><strong>${num(profit,m?1:0)}</strong></div><div><span>${m?'正式V3 損切り判定':'損切り判定サヤ'}</span><strong>${num(stop,m?1:0)}</strong></div><div><span>${manual||p?'評価サヤ損益':'最大保有'}</span><strong>${manual||p?sign(pnl,m?1:0)+' pt':m?'15営業日':'30営業日'}</strong></div></div><p class="thresholdnote">${m?'利益300pt以上を確保し、前日までに有利な動きがあった後の日次反転で決済予約。損切り800pt、保有14セッション経過で翌有効日終値の期限決済を予約。元サイトの暫定−900pt水準：'+num(entry-side*900,1)+'。':'NYダウ売り・日経225買いの縮小ポジション。終値で利確・損切りを判定し、翌共通取引日始値で決済。保有30セッション目の終値で期限決済を予約。'}${held!==null?'<br>入力日以降の共通営業日数：'+held+' / 最大 '+(m?15:30):''}${invalidDate?'<br>約定日が価格履歴にありません。日付を確認してください。':''}${pending?'<br><b>'+pending+'条件成立：翌共通取引日始値で決済予定</b>':''}${!m&&!manual&&!sim.available?'<br>始値がないため、仮想保有は計算できません。実際の建値を入力してください。':''}${!m&&!p&&!manual&&sim.pendingEntry?'<br>次の共通有効日始値でエントリー予定。建値は未確定。':''}${m&&(manual)?'<br>概算評価額（1セット・価格差のみ）：'+sign(pnl*100,0)+'円':''}</p>`;}
function render(){const focus=document.activeElement;$('#dashboard').innerHTML=section('metals')+section('indices');for(const kind of ['metals','indices'])draw(kind);}
function draw(kind){const a=state[kind],m=kind==='metals',data=a.range?a.data.slice(-a.range):a.data,c=$(`[data-chart="${kind}"]`),ctx=c.getContext('2d'),w=c.clientWidth,h=250,ratio=window.devicePixelRatio||1;c.width=w*ratio;c.height=h*ratio;ctx.scale(ratio,ratio);const left=64,right=w-20,top=12,bottom=217;let vals=data.map(r=>r.spread);if(!m)vals.push(...data.flatMap(r=>[r.ma20,r.ma50]).filter(v=>v!==null));else vals.push(2200,2500);let min=Math.min(...vals),max=Math.max(...vals),pad=(max-min)*.12||100;min-=pad;max+=pad;const x=i=>left+(right-left)*i/Math.max(1,data.length-1),y=v=>bottom-(bottom-top)*(v-min)/(max-min);ctx.font='12px system-ui';ctx.fillStyle='#7a8c9d';ctx.strokeStyle='#e9eef3';ctx.lineWidth=1;for(let i=0;i<5;i++){const v=min+(max-min)*i/4;ctx.beginPath();ctx.moveTo(left,y(v));ctx.lineTo(right,y(v));ctx.stroke();ctx.textAlign='right';ctx.fillText(num(v,0),left-10,y(v)+4);}ctx.textAlign='left';ctx.fillText(data[0].date.slice(5),left,241);ctx.textAlign='right';ctx.fillText(data.at(-1).date.slice(5),right,241);if(m){ctx.setLineDash([4,5]);ctx.strokeStyle='#a1b0bf';for(const v of [2200,2500]){ctx.beginPath();ctx.moveTo(left,y(v));ctx.lineTo(right,y(v));ctx.stroke();}ctx.setLineDash([]);}for(const [key,color] of m?[['spread','#236fbd']]:[['ma50','#d49734'],['ma20','#0a8b83'],['spread','#236fbd']]){ctx.strokeStyle=color;ctx.lineWidth=key==='spread'?2.3:1.5;ctx.beginPath();let started=false;for(let i=0;i<data.length;i++){const v=data[i][key];if(v===null)continue;if(!started){ctx.moveTo(x(i),y(v));started=true;}else ctx.lineTo(x(i),y(v));}ctx.stroke();}ctx.fillStyle='#236fbd';ctx.beginPath();ctx.arc(x(data.length-1),y(data.at(-1).spread),3.5,0,Math.PI*2);ctx.fill();c.onpointermove=event=>{const rect=c.getBoundingClientRect(),i=Math.min(data.length-1,Math.max(0,Math.round((event.clientX-rect.left-left)/(right-left)*Math.max(1,data.length-1)))),r=data[i];$(`[data-readout="${kind}"]`).textContent=r.date+'　サヤ '+num(r.spread,m?1:0)+' pt　前日比 '+sign(r.change,m?1:0)+(m?'':'　20MA '+num(r.ma20,0)+' / 50MA '+num(r.ma50,0));};}
document.addEventListener('click',event=>{const range=event.target.closest('[data-range]'),exp=event.target.closest('[data-export]');if(range){state[range.dataset.range].range=+range.dataset.days;render();}if(exp){const k=exp.dataset.export,a=state[k],heads=k==='metals'?['date','silver','platinum']:['date','ny_dow_open','ny_dow_close','nikkei225_open','nikkei225_close'];const text=heads.join(',')+'\n'+a.rows.map(r=>heads.map(h=>r[h]??'').join(',')).join('\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=k+'-'+a.rows.at(-1).date+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
document.addEventListener('change',async event=>{const input=event.target;if(input.dataset.import){const k=input.dataset.import,file=input.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('5MB以下のCSVを選択してください。');const rows=E.parse(await file.text(),k);if(rows.length>20000)throw Error('20,000行以下のCSVを選択してください。');state[k].rows=rows;state[k].name=file.name;render();notify(file.name+' を読み込み、'+rows.length+'日分を再計算しました。次回用にCSVを書き出せます。');}catch(error){notify(error.message,true);input.value='';}}else if(input.dataset.field){const k=input.dataset.kind,f=input.dataset.field;state[k][f]=f==='side'?+input.value:input.value;$(`[data-exit="${k}"]`).innerHTML=exitView(k);}});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.field==='entry'){const k=input.dataset.kind;state[k].entry=input.value;$(`[data-exit="${k}"]`).innerHTML=exitView(k);}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{for(const k of ['metals','indices'])if(state[k].data)draw(k);},150);});
async function init(){try{const responses=await Promise.all([fetch('./silver-platinum.csv'),fetch('./dow-nikkei.csv')]);for(let i=0;i<responses.length;i++){if(!responses[i].ok)throw Error('初期価格を取得できません。ページを再読み込みしてください。');const k=i?'indices':'metals';state[k].rows=E.parse(await responses[i].text(),k);}render();}catch(error){$('#dashboard').textContent='データ読み込みに失敗しました。';notify(error.message,true);}}init();
